export async function fetchSignatureFromLegacyApi(
  email: string
): Promise<string> {
  const url =
    "https://signature.fgautomazioni.it/signature-api" +
    "?cmd=getEmailSign" +
    "&email=" +
    encodeURIComponent(email) +
    "&applicationId=FGIT" +
    "&appId=FGIT";

  const response = await fetch(url, {
    method: "GET",
    cache: "no-store",
  });

  if (!response.ok) {
    throw new Error(
      `Legacy API HTTP ${response.status}`
    );
  }

  const html = await response.text();

  if (!html || html.trim() === "") {
    throw new Error(
      "La Legacy API ha restituito una firma vuota."
    );
  }

  return html;
}